&lt;span class="k"&gt;export&lt;/span&gt; &lt;span class="k"&gt;default&lt;/span&gt; &lt;span class="nx"&gt;AICreativeStudioCanvas&lt;/span&gt;&lt;span class="p"&gt;;&lt;/span&gt;
